/*
	BroadcastMsgMapper.insertBroadcastMsg 대량 발송 등록
*/


		INSERT INTO T_BROADCAST_MSG (
			B_MSG_KEY, LOGIN_ID, USER_ID, TITLE, MSG, IN_TIME, CALLBACK_NO, REQ_TIME, CNT, SUCC_CNT, FAIL_CNT, STATUS, SVC_TYPE, SEND_INFO
		) VALUES(
			#{bMsgKey}, #{loginId}, #{userId}, #{title}, CAST(#{msg} AS VARCHAR(2000)), GETDATE(), #{callbackNo}, #{reqTime}, #{cnt}, #{succCnt}, #{failCnt}, #{status}, #{svcType}, #{sendInfo}
		)


		INSERT INTO T_BROADCAST_MSG (
			B_MSG_KEY, LOGIN_ID, USER_ID, TITLE, MSG, IN_TIME, CALLBACK_NO, REQ_TIME, CNT, SUCC_CNT, FAIL_CNT, STATUS, SVC_TYPE, SEND_INFO
		) VALUES(
			#{bMsgKey}, #{loginId}, #{userId}, #{title}, CAST(#{msg} AS VARCHAR(2000)), GETDATE(), #{callbackNo}, ${reqTime}, #{cnt}, #{succCnt}, #{failCnt}, #{status}, #{svcType}, #{sendInfo}
		)

mapper.update:
/*
	BroadcastMsgMapper.updateBroadcastMsgCountByType 대량 발송 타입별 성공 / 실패 카운트 업데이트
*/


		UPDATE T_BROADCAST_MSG SET SUCC_CNT = #{cnt} WHERE B_MSG_KEY = #{bMsgKey}


		UPDATE T_BROADCAST_MSG SET FAIL_CNT = #{cnt} WHERE B_MSG_KEY = #{bMsgKey}

/*
	BroadcastMsgMapper.updateBroadcastMsgCount 대량 발송 성공 / 실패 카운트 업데이트
*/
	UPDATE T_BROADCAST_MSG SET SUCC_CNT = #{succCnt}, FAIL_CNT = #{failCnt} WHERE B_MSG_KEY = #{bMsgKey}
